<!doctype html><html lang="fr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Sécurité · SAGASTOCK</title><style>:root{--o:#f47a20;--s:#fff7f0}*{box-sizing:border-box}body{margin:0;font-family:system-ui;background:var(--s);color:#382319}header{background:var(--o);padding:18px 5%;color:white}header a{color:white;margin-right:20px}main{max-width:1250px;margin:28px auto;padding:0 20px}.card{background:white;padding:22px;border-radius:16px;margin-bottom:22px;box-shadow:0 10px 30px #7a350015}.grid{display:grid;grid-template-columns:1fr 1fr;gap:16px}.role{border-top:1px solid #eedfd4;padding:18px 0}input{padding:10px;border:1px solid #d8c8bb;border-radius:8px}button{background:var(--o);color:white;border:0;padding:10px 14px;border-radius:8px;font-weight:700}.danger{background:#b42318}.permissions{display:flex;flex-wrap:wrap;gap:10px;margin:12px 0}.permissions label{background:#fff1e7;padding:7px 9px;border-radius:8px}table{width:100%;border-collapse:collapse}th,td{text-align:left;padding:10px;border-bottom:1px solid #eee;font-size:14px}.message{padding:12px;background:#eaf8ef;border-radius:8px}@media(max-width:800px){.grid{grid-template-columns:1fr}table{display:block;overflow:auto}}</style></head><body><header><a href="{{ route('dashboard') }}">← Utilisateurs</a><a href="{{ route('profile.show') }}">Mon profil</a></header><main><h1>Sécurité et audit</h1>@if(session('status'))<p class="message">{{ session('status') }}</p>@endif @if($errors->any())<p class="message">{{ $errors->first() }}</p>@endif<div class="grid"><section class="card"><h2>Nouveau rôle</h2><form method="post" action="{{ route('security.roles.store') }}">@csrf<p><input name="code" placeholder="code_du_role" required> <input name="name" placeholder="Nom du rôle" required></p><div class="permissions">@foreach($permissions as $permission)<label><input type="checkbox" name="permission_ids[]" value="{{ $permission->id }}"> {{ $permission->name }}</label>@endforeach</div><button>Créer le rôle</button></form></section><section class="card"><h2>Principes</h2><p>Les rôles système sont protégés. Un rôle attribué ne peut pas être supprimé. Toutes les modifications sensibles sont réservées aux administrateurs autorisés.</p></section></div><section class="card"><h2>Rôles existants</h2>@foreach($roles as $role)<article class="role"><form method="post" action="{{ route('security.roles.update',$role) }}">@csrf @method('PUT')<input name="code" value="{{ $role->code }}" required> <input name="name" value="{{ $role->name }}" required> @if($role->is_system)<strong>Rôle système</strong>@endif<div class="permissions">@foreach($permissions as $permission)<label><input type="checkbox" name="permission_ids[]" value="{{ $permission->id }}" @checked($role->permissions->contains($permission))> {{ $permission->name }}</label>@endforeach</div><button>Enregistrer</button></form>@if(!$role->is_system)<form method="post" action="{{ route('security.roles.destroy',$role) }}">@csrf @method('DELETE')<button class="danger">Supprimer</button></form>@endif</article>@endforeach</section><section class="card"><h2>Journal d’audit</h2><form method="get"><input name="event" value="{{ request('event') }}" placeholder="Filtrer par événement"><button>Filtrer</button></form><table><thead><tr><th>Date</th><th>Utilisateur</th><th>Événement</th><th>Objet</th><th>Adresse IP</th></tr></thead><tbody>@forelse($logs as $log)<tr><td>{{ $log->created_at }}</td><td>{{ $log->user?->email ?? 'Système' }}</td><td>{{ $log->event }}</td><td>{{ class_basename($log->auditable_type ?? '') }} #{{ $log->auditable_id }}</td><td>{{ $log->ip_address }}</td></tr>@empty<tr><td colspan="5">Aucun événement.</td></tr>@endforelse</tbody></table>{{ $logs->withQueryString()->links() }}</section></main></body></html>
